```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    while (plik >> n) {
        int mx = 0, mn = 9;
        int tmp = n;
        while (tmp > 0) {
            int c = tmp % 10;
            if (c > mx) mx = c;
            if (c < mn) mn = c;
            tmp /= 10;
        }
        int roznica = mx - mn;
        cout << n << ": max=" << mx << ", min=" << mn << ", roznica=" << roznica;
        if (roznica >= 7) {
            cout << " -> TAK" << endl;
            ile++;
        } else {
            cout << endl;
        }
    }
    cout << "Liczby z roznica cyfr >= 7: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Inicjalizacja `mx=0, mn=9` gwarantuje poprawna aktualizacje przy pierwszej cyfrze. Roznica max-min mierzy "rozpietosc" cyfr.

